create table if not exists public.users(id bigint generated by default as identity primary key, username text not null unique, password text not null, created_at timestamptz not null default now());
create table if not exists public.rooms(id bigint generated by default as identity primary key, name text not null, type text not null, description text not null, image_url text not null, guests int not null default 2, size text not null, price_label text not null, is_free_night boolean not null default false);
create table if not exists public.reservations(id bigint generated by default as identity primary key, user_id bigint not null references public.users(id) on delete cascade, room_id bigint not null references public.rooms(id) on delete cascade, check_in date not null, check_out date not null, status text not null default 'Confirmed', created_at timestamptz not null default now(), unique(user_id,room_id));
insert into public.rooms(name,type,description,image_url,guests,size,price_label,is_free_night) values
('Garden Deluxe','Deluxe Room','A calm modern room with a garden-facing view, queen bed and private balcony.','https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=1200&q=85',2,'32 m²','FREE ONE NIGHT',true),
('Ocean Premier','Premier Room','Bright coastal-inspired accommodation with a king bed and panoramic view.','https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1200&q=85',2,'40 m²','FROM ₱4,800 / NIGHT',false),
('Family Residence','Family Suite','A spacious suite designed for families with two beds and a sitting area.','https://images.unsplash.com/photo-1591088398332-8a7791972843?auto=format&fit=crop&w=1200&q=85',4,'58 m²','FROM ₱7,200 / NIGHT',false)
on conflict do nothing;
alter table public.users enable row level security; alter table public.rooms enable row level security; alter table public.reservations enable row level security;
drop policy if exists "Public can browse rooms" on public.rooms; create policy "Public can browse rooms" on public.rooms for select to anon,authenticated using(true);
drop policy if exists "Anyone can create demo accounts" on public.users; create policy "Anyone can create demo accounts" on public.users for insert to anon,authenticated with check(true);
drop policy if exists "Anyone can check demo login" on public.users; create policy "Anyone can check demo login" on public.users for select to anon,authenticated using(true);
drop policy if exists "Anyone can create demo reservations" on public.reservations; create policy "Anyone can create demo reservations" on public.reservations for insert to anon,authenticated with check(true);
drop policy if exists "Anyone can view demo reservations" on public.reservations; create policy "Anyone can view demo reservations" on public.reservations for select to anon,authenticated using(true);
